mapper.select:
SELECT cut.id 'id', cut.task_order_id, cut.cut_number 'cutNumber', cut.scheduling_time 'scheduleTime', cut.ask_complete_time 'completeTime', cut.issue_user_id 'userId', cut.bool_off_line 'offLineType', us.`name`'userName', cut.production_line_id 'productionLine.id' , line.`name` 'productionLine.name', cut.workshop_id 'workshop.id', ws.`name` 'workshop.name', cut.groups_id 'group.id', gro.`name` 'group.name', SUM( process.task_quantity ) 'taskQuantity', CASE #{processType} WHEN 4 THEN cut.cut_print_quantity ELSE cut.hole_print_quantity END 'printQuantity', SUM( process.task_quantity * par.net_weight ) 'taskNetWeight', SUM( process.task_quantity * par.gross_weight ) 'taskGrossWeight', ord.cut_config_id 'config.id', ord.order_number 'orderNumber', config.`name` 'config.name', cutTeamConfig.device_type 'cutType', cut.bool_nest_cut_enum 'boolNestCut' FROM mes_building_nest_cut_plate cut LEFT JOIN mes_building_task_process process ON cut.id = process.nest_cut_plate_id AND process.bool_delete_enum = 0
and process.project_id in
#{projectId}
AND process.monomer_id in
#{monomerId}
AND process.area_id in
#{areaId}
LEFT JOIN mes_building_task_order ord ON ord.id=cut.task_order_id AND ord.bool_delete_enum=0 LEFT JOIN mes_building_machine_part_team_detail cutTeamConfig ON cutTeamConfig.id =cut.cut_config_id AND cutTeamConfig.bool_delete_enum=0 LEFT JOIN mes_building_cut_config config ON cutTeamConfig.device_type = config.name AND config.bool_delete_enum=0 LEFT JOIN tech_machine_part par ON par.id = process.product_id AND par.bool_delete_enum = 0 LEFT JOIN sys_user us ON cut.issue_user_id = us.id LEFT JOIN mes_building_production_line line ON line.id = cut.production_line_id AND line.bool_delete_enum = 0 LEFT JOIN mes_building_workshop ws ON ws.id = cut.workshop_id AND ws.bool_delete_enum = 0 LEFT JOIN mes_building_groups gro ON cut.groups_id = gro.id AND gro.bool_delete_enum = 0
LEFT JOIN mes_building_process pr ON pr.id = process.process_id
CASE WHEN cut.bool_off_line = 0 THEN process.process_id IN
#{processId}
WHEN cut.bool_off_line = 1 THEN TRUE END
AND cut.bool_delete_enum=0
AND DATE_FORMAT( cut.scheduling_time, '%Y' )=DATE_FORMAT( #{localDateTime}, '%Y' )
AND cut.workshop_id = #{workshopId}
AND cut.cut_number LIKE CONCAT('%',#{cutNumber},'%')
and case #{processType} WHEN 4 THEN cut.cut_print_quantity ELSE cut.hole_print_quantity END >0
and case #{processType} WHEN 4 THEN cut.cut_print_quantity ELSE cut.hole_print_quantity END =0
AND cut.bool_nest_cut_enum=#{boolNestCut}
AND cut.id IN ( SELECT par.mes_building_nest_cut_plate_id FROM mes_building_nest_cut_plate_part par LEFT JOIN tech_machine_part mach ON par.part_id = mach.id AND mach.bool_delete_enum = 0 WHERE mach.bool_delete_enum=0 AND mach.area_id in
#{areaId}
)
AND cut.task_order_id IN ( SELECT ta.task_order_id FROM mes_building_task ta LEFT JOIN tech_machine_part mach ON ta.product_id = mach.id AND mach.bool_delete_enum = 0 WHERE mach.bool_delete_enum = 0 AND mach.area_id in
#{areaId}
AND mach.serial_number like CONCAT('%',#{serialNumber},'%') )
AND pr.type = #{processType} AND cut.bool_off_line=0
AND ord.cut_config_id =#{cutConfigId}
GROUP BY cut.id order by cut.scheduling_time desc
